    pontos:[ { ico:'🎓', t:'Capacitação permanente', d:'polícias, guarda municipal, bombeiros e demais profissionais' }, { ico:'🏥', t:'Centros de atendimento', d:'integral e multidisciplinar para mulheres e dependentes' }, { ico:'🧑‍🏫', t:'Reabilitação de agressores', d:'centros de educação e de reabilitação' } ],
