    regra:'A audiência do art. 16 tem por objetivo {0|confirmar a retratação da vítima}, não a representação, e só é designada mediante {1|manifestação expressa de seu desejo de se retratar}, apresentada {2|antes do recebimento da denúncia}.',
    pontos:[ { ico:'🎯', t:'Objetivo', d:'confirmar a retratação, não a representação' }, { ico:'🗣️', t:'Manifestação expressa', d:'por escrito ou oralmente, pela vítima' }, { ico:'📅', t:'Momento', d:'antes do recebimento da denúncia' } ],
