    pontos:[ { ico:'⚡', t:'De imediato', d:'o juiz aplica assim que constatada a violência' }, { ico:'🚪', t:'Afastamento do lar', d:'inciso II do art. 22' }, { ico:'🛡️', t:'Em favor da ofendida', d:'a medida obriga o agressor, não a ofendida' } ],
