    regra:'Configura violência doméstica e familiar contra a mulher qualquer {0|ação ou omissão baseada no gênero} que lhe cause {1|morte, lesão, sofrimento físico, sexual ou psicológico} e dano {2|moral ou patrimonial}.',
    pontos:[ { ico:'⚧️', t:'Baseada no gênero', d:'é o elemento que define a incidência da lei' }, { ico:'💥', t:'Resultado', d:'morte, lesão ou sofrimento físico, sexual ou psicológico' }, { ico:'💰', t:'Dano moral ou patrimonial', d:'também entra no conceito' } ],
