    pontos:[ { ico:'🏗️', t:'Equipamentos públicos', d:'especializados, para mulheres e autores de violência' }, { ico:'➕', t:'Ampliar o quantitativo', d:'meta expressa do Eixo 4' }, { ico:'🏠', t:'Casas da Mulher Brasileira', d:'serviço do Eixo 4, enfrentamento da violência' } ],
